      productInterest: productName,
      quantity: values.quantity,
      additionalDetails: values.additionalDetails ?? '',
    };

    createInquiry(inquiryRequest, {
      onSuccess: () => {
        toast.success('Inquiry submitted successfully!');
        form.reset();
