  if (isError) {
    return (
      <div className="container mx-auto py-8 px-4 text-red-600">
        <h1 className="text-3xl font-bold mb-6">Manage Inquiries</h1>
        <p>Error loading inquiries: {error?.message}</p>
      </div>
    );
  }

  return (
    <div className="container mx-auto py-8 px-4">
      <h1 className="text-3xl font-bold mb-6">Manage Inquiries</h1>
      <InquiryTable onView={handleViewInquiry} />

      <Dialog open={isDetailViewOpen} onOpenChange={setIsDetailViewOpen}>
        <DialogContent className="sm:max-w-[800px]">
          {selectedInquiry && (
            <InquiryDetailView
              inquiry={selectedInquiry}
              onClose={handleCloseDetailView}
              onStatusUpdate={handleStatusUpdate}
            />
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { LookbookTable } from '@/components/lookbook/admin/LookbookTable';
import LookbookForm from '@/components/lookbook/admin/LookbookForm';
import { DeleteConfirmationDialog } from '@/components/shared/DeleteConfirmationDialog';
import { useLookbookEntries, useDeleteLookbookEntry } from '@/hooks/lookbookHooks';
import { LookbookEntryDto } from '@/types/lookbook';
import { toast } from 'sonner';
import { Skeleton } from '@/components/ui/skeleton';

export default function AdminLookbookPage(): React.JSX.Element {
  const { data: lookbookEntries, isLoading, isError, error } = useLookbookEntries();
  const { mutate: deleteLookbookEntry } = useDeleteLookbookEntry();

  const [isFormOpen, setIsFormOpen] = useState<boolean>(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState<boolean>(false);
  const [selectedEntry, setSelectedEntry] = useState<LookbookEntryDto | null>(null);

  const handleEdit = (entry: LookbookEntryDto): void => {
    setSelectedEntry(entry);
    setIsFormOpen(true);
  };

  const handleDelete = (entry: LookbookEntryDto): void => {
    setSelectedEntry(entry);
    setIsDeleteDialogOpen(true);
  };

  const confirmDelete = (): void => {
    if (selectedEntry) {
      deleteLookbookEntry(selectedEntry.id, {
        onSuccess: () => {
          toast.success('Lookbook entry deleted successfully.');
          setIsDeleteDialogOpen(false);
          setSelectedEntry(null);
        },
        onError: (err) => {
          toast.error(`Failed to delete lookbook entry: ${err.message}`);
        },
      });
    }
  };

  const handleFormClose = (): void => {
    setIsFormOpen(false);
    setSelectedEntry(null);
  };

  const handleFormSuccess = (): void => {
    toast.success('Lookbook entry saved successfully.');
    handleFormClose();
  };

  if (isLoading) {
    return (
      <div className="space-y-4 p-4">
        <Skeleton className="h-10 w-48" />
        <Skeleton className="h-12 w-full" />
        <Skeleton className="h-96 w-full" />
      </div>
    );
  }

  if (isError) {
    return (
      <div className="p-4 text-red-600">
        Error loading lookbook entries: {error instanceof Error ? error.message : 'Unknown error'}
      </div>
    );
  }

  return (
    <div className="container mx-auto py-8">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold">Manage Lookbook Entries</h1>
        <Button onClick={() => { setSelectedEntry(null); setIsFormOpen(true); }} data-testid="create-lookbook-entry-cta">
          Add New Entry
        </Button>
      </div>

      <LookbookTable
        entries={lookbookEntries || []}
        onEdit={handleEdit}
        onDelete={handleDelete}
      />

      <Dialog open={isFormOpen} onOpenChange={setIsFormOpen}>
        <DialogContent className="sm:max-w-[600px]">
          <DialogHeader>
            <DialogTitle>{selectedEntry ? 'Edit Lookbook Entry' : 'Create New Lookbook Entry'}</DialogTitle>
          </DialogHeader>
          <LookbookForm
            entry={selectedEntry}
            onClose={handleFormClose}
            onSuccess={handleFormSuccess}
          />
        </DialogContent>
      </Dialog>

      <DeleteConfirmationDialog
        isOpen={isDeleteDialogOpen}
        onClose={() => setIsDeleteDialogOpen(false)}
        onConfirm={confirmDelete}
        itemType="lookbook entry"
        itemName={selectedEntry?.title || ''}
      />
    </div>
  );
}

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { ProductTable } from '@/components/product/admin/ProductTable';
import { ProductForm } from '@/components/product/admin/ProductForm';
import { DeleteConfirmationDialog } from '@/components/shared/DeleteConfirmationDialog';
import { useProducts, useDeleteProduct } from '@/hooks/productHooks';
import { ProductDto } from '@/types/product';
import { toast } from 'sonner';
import { PlusCircle } from 'lucide-react';

export default function AdminProductsPage() {
  const { data: products, isLoading, isError, error } = useProducts();
  const { mutate: deleteProduct, isPending: isDeleting } = useDeleteProduct();

  const [isFormOpen, setIsFormOpen] = useState<boolean>(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState<boolean>(false);
  const [selectedProduct, setSelectedProduct] = useState<ProductDto | null>(null);
  const [productToDelete, setProductToDelete] = useState<ProductDto | null>(null);

  const handleEditProduct = (product: ProductDto): void => {
    setSelectedProduct(product);
    setIsFormOpen(true);
  };

  const handleDeleteProduct = (product: ProductDto): void => {
    setProductToDelete(product);
    setIsDeleteDialogOpen(true);
  };

  const confirmDelete = (): void => {
    if (productToDelete) {
      deleteProduct(productToDelete.id, {
        onSuccess: () => {
          toast.success('Product deleted successfully.');
          setIsDeleteDialogOpen(false);
          setProductToDelete(null);
        },
        onError: (err) => {
          toast.error(`Failed to delete product: ${err.message}`);
        },
      });
    }
  };

  const handleFormSuccess = (): void => {
    setIsFormOpen(false);
    setSelectedProduct(null);
    toast.success(selectedProduct ? 'Product updated successfully.' : 'Product created successfully.');
  };

  if (isLoading) {
    return (
      <div className="flex justify-center items-center h-64">
        <p>Loading products...</p>
      </div>
    );
  }

  if (isError) {
    return (
      <div className="text-center text-red-500">
        <p>Error loading products: {error?.message}</p>
      </div>
    );
  }

  return (
    <div className="container mx-auto py-8">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-[#333333]">Product Management</h1>
        <Dialog open={isFormOpen} onOpenChange={setIsFormOpen}>
          <DialogTrigger asChild>
            <Button
              className="bg-[#D4AF37] hover:bg-[#C2A032] text-white font-semibold rounded-md px-6 py-2 transition-all duration-200"
              onClick={() => {
                setSelectedProduct(null);
                setIsFormOpen(true);
              }}
              data-testid="add-product-cta"
            >
              <PlusCircle className="mr-2 h-4 w-4" /> Add Product
            </Button>
          </DialogTrigger>
          <DialogContent className="sm:max-w-[600px]">
            <DialogHeader>
              <DialogTitle>{selectedProduct ? 'Edit Product' : 'Create New Product'}</DialogTitle>
            </DialogHeader>
            <ProductForm product={selectedProduct} onClose={() => setIsFormOpen(false)} onSuccess={handleFormSuccess} />
          </DialogContent>
        </Dialog>
      </div>

      <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-100">
        {products && products.length > 0 ? (
          <ProductTable products={products} onEdit={handleEditProduct} onDelete={handleDeleteProduct} />
        ) : (
          <div className="text-center py-10">
            <p className="text-gray-500">No products found. Add a new product to get started.</p>
          </div>
        )}
      </div>

      <DeleteConfirmationDialog
        isOpen={isDeleteDialogOpen}
        onClose={() => setIsDeleteDialogOpen(false)}
        onConfirm={confirmDelete}
        itemType="product"
        itemName={productToDelete?.name ?? ''}
      />
    </div>
  );
}
